DECLARE @ID_TRT_ALI BIGINT = <?=odiRef.getSession("SESS_NO") ?>;
DECLARE @LB_PROJET NVARCHAR(50) = N'#INEO.V_NOM_PROJET';
DECLARE @H_FRONTIERE TIME(0) = '07:45:00';

DECLARE
    @fin_extraction    DATETIME2(3),
    @nb_inst_sans_date INT,
    @dt_jour_prec      DATE,
    @jour              DATE,
    @jour_suivant      DATE,
    @frontiere         DATETIME2(3),
    @nb_bornes         INT = 0,
    @nb_inst_absentes  INT = 0,
    @premiere          DATE,
    @derniere          DATE,
    @dt_step           DATETIME2(3) = SYSDATETIME(),
    @dt_pose           DATETIME2(3);

/* ============================================================================
   1. DETERMINATION DE LA COUVERTURE COMMUNE DE L'EXTRACTION
============================================================================ */

/* Seuls les flux DELTA dépendent de la capture, et seule une extraction de
   type CDC fait avancer la couverture : après une photo INIT ou FULL, la
   journée n'est complète qu'à la prochaine plage de traces. */
SELECT
    @fin_extraction = MIN(A.DT_FIN_LSN),
    @nb_inst_sans_date = SUM (CASE WHEN A.DT_FIN_LSN IS NULL THEN 1 ELSE 0 END)
FROM <?=odiRef.getObjectName("L", "OIT_TEC_AUDIT_CDC", "MSSQL_ODS", "D") ?> AS A
WHERE A.LB_INSTANCE IN
(
    SELECT DISTINCT F.LB_SOURCE
    FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
    WHERE F.LB_PROJET = @LB_PROJET
      AND F.FL_ACTIF = 1
      AND F.CD_MODE_ENTREE = N'DELTA'
      AND F.LB_SOURCE IS NOT NULL
);

/* Instances DELTA attendues mais absentes de l'audit : leur fichier n'a pas
   été livré, la couverture est calculée sans elles. Signalé dans le bilan. */
SELECT @nb_inst_absentes = COUNT(*)
FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
WHERE F.LB_PROJET = @LB_PROJET
  AND F.FL_ACTIF = 1
  AND F.CD_MODE_ENTREE = N'DELTA'
  AND F.LB_SOURCE IS NOT NULL
  AND NOT EXISTS
  (
      SELECT 1
      FROM <?=odiRef.getObjectName("L", "OIT_TEC_AUDIT_CDC", "MSSQL_ODS", "D") ?> AS A
      WHERE A.LB_INSTANCE = F.LB_SOURCE
  );

/* Un projet sans aucun flux DELTA n'a pas d'extraction a attendre : sa
   couverture est l'instant present, et chaque journee dont la frontiere est
   passee devient eligible. Les flux FULL et CSV sont ainsi traites sans
   dependre d'une capture qui n'existe pas. */
IF NOT EXISTS
(
    SELECT 1
    FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
    WHERE F.LB_PROJET = @LB_PROJET
      AND F.FL_ACTIF = 1
      AND F.CD_MODE_ENTREE = N'DELTA'
)
BEGIN
    SET @fin_extraction = SYSDATETIME();
    SET @nb_inst_sans_date = 0;
END;

/* Plafond a l'instant present. Une trace dont la date de commit est dans le
   futur - horloge source dereglee, saisie manuelle - tirerait la couverture
   au-dela d'aujourd'hui et poserait des bornes sur des journees pas encore
   arrivees, ce qui bloquerait le quotidien. On borne donc la couverture a
   maintenant : les journees passees se traitent normalement, et la trace au
   futur reste dans le sas jusqu'a ce que sa journee soit reellement atteinte. */
IF @fin_extraction > SYSDATETIME()
    SET @fin_extraction = SYSDATETIME();

/* Si la couverture commune ne peut pas être déterminée,
   aucune journée n'est traitée. */

IF @fin_extraction IS NULL OR ISNULL(@nb_inst_sans_date, 0) > 0
BEGIN
    /* Cas normal après une initialisation : l'audit ne porte que des lignes
       INIT. Les bornes reprendront à la première extraction CDC. */
    INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
    (
        ID_TRT_ALI,
        LB_PROJET,
        LB_CHARGEMENT,
        LB_SOURCE,
        LB_CIBLE,
        NB_LIGNE,
        CD_STATUT,
        LB_ERREUR,
        DT_DEBUT,
        DT_FIN
    )
    VALUES
    (
        @ID_TRT_ALI,
        @LB_PROJET,
        N'POSE BORNE',
        N'OIT_TEC_AUDIT_CDC',
        N'ORT_BORNE_JOURNEE',
        0,
        N'OK',
        N'IGNORE: couverture d''extraction indéterminable ('
        + CONVERT ( NVARCHAR(10), ISNULL(@nb_inst_sans_date, 0) )
        + N' instance(s) sans DT_FIN_LSN, audit vide ou sans ligne CDC). '
        + N'Aucune journée bornée.',
        @dt_step,
        SYSDATETIME()
    );

    RETURN;
END;


/* ============================================================================
   2. RECUPERATION DE LA DERNIERE JOURNEE DEJA BORNEE
============================================================================ */

SELECT @dt_jour_prec = MAX(CONVERT(DATE, DT_JOUR))
FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
WHERE LB_PROJET = @LB_PROJET;

/* Une borne INIT doit avoir été créée avant le traitement quotidien. */

IF @dt_jour_prec IS NULL
BEGIN
    INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
    (
        ID_TRT_ALI,
        LB_PROJET,
        LB_CHARGEMENT,
        LB_SOURCE,
        LB_CIBLE,
        NB_LIGNE,
        CD_STATUT,
        LB_ERREUR,
        DT_DEBUT,
        DT_FIN
    )
    VALUES
    (
        @ID_TRT_ALI,
        @LB_PROJET,
        N'POSE BORNE',
        N'OIT_TEC_AUDIT_CDC',
        N'ORT_BORNE_JOURNEE',
        0,
        N'OK',
        N'AVERTISSEMENT: aucune borne initiale '
        + N'(TYPE_BORNE = INIT). '
        + N'Executer G_DWH_MEP/01_DWH_INIT_MEP.sql.',
        @dt_step,
        SYSDATETIME()
    );

    RETURN;
END;

/* ============================================================================
   3. POSE DES BORNES QUOTIDIENNES

   Une borne est créée uniquement lorsque l'extraction couvre entièrement
   la journée fonctionnelle jusqu'à la frontière du jour ouvrable suivant.
============================================================================ */

WHILE 1 = 1
BEGIN
    SET @jour = NULL;
    SET @jour_suivant = NULL;
    SET @frontiere = NULL;

    /* Première journée ouvrable non encore bornée. */
    SELECT TOP (1) @jour = CONVERT(DATE, DT_CAL)
    FROM <?=odiRef.getObjectName("L", "PRTCAL", "MSSQL_DWH", "D") ?>
    WHERE FL_OVR = 1
      AND CONVERT(DATE, DT_CAL) > @dt_jour_prec
    ORDER BY DT_CAL;

    /* Calendrier épuisé. */
    IF @jour IS NULL BREAK;

    /* Journée ouvrable suivante permettant de calculer la frontière. */
    SELECT TOP (1) @jour_suivant = CONVERT(DATE, DT_CAL)
    FROM <?=odiRef.getObjectName("L", "PRTCAL", "MSSQL_DWH", "D") ?>
    WHERE FL_OVR = 1
      AND CONVERT(DATE, DT_CAL) > @jour
    ORDER BY DT_CAL;

    /* La frontière ne peut pas être calculée.
       Le calendrier PRTCAL doit être prolongé. */
    IF @jour_suivant IS NULL BREAK;

    SET @frontiere =
        DATETIME2FROMPARTS
        (
            DATEPART(YEAR,  @jour_suivant),
            DATEPART(MONTH, @jour_suivant),
            DATEPART(DAY,   @jour_suivant),
            DATEPART(HOUR,   @H_FRONTIERE),
            DATEPART(MINUTE, @H_FRONTIERE),
            0,
            0,
            3
        );

    /* La journée n'est pas encore entièrement couverte par l'extraction. */
    IF @fin_extraction < @frontiere BREAK;
    SET @dt_pose = SYSDATETIME();

    INSERT INTO <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
    (
        LB_PROJET,
        DT_JOUR,
        DT_BORNE,
        TYPE_BORNE,
        ORIGINE_VALEUR,
        FL_TRAITE,
        DT_POSE,
        COMMENTAIRE
    )
    VALUES
    (
        @LB_PROJET,
        CONVERT(DATETIME2(3), @jour),
        @frontiere,
        N'QUOTIDIEN',
        N'AUDIT_CDC',
        0,
        @dt_pose,
        N'Borne posee automatiquement a partir de la couverture '
        + N'OIT_TEC_AUDIT_CDC. Fin extraction commune : '
        + CONVERT(NVARCHAR(23), @fin_extraction, 121)
    );

    IF @nb_bornes = 0
       SET @premiere = @jour;

    SET @derniere = @jour;
    SET @nb_bornes = @nb_bornes + 1;
    SET @dt_jour_prec = @jour;
END;


/* ============================================================================
   4. AUDIT RECAPITULATIF
============================================================================ */

INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
(
    ID_TRT_ALI,
    LB_PROJET,
    LB_CHARGEMENT,
    LB_SOURCE,
    LB_CIBLE,
    NB_LIGNE,
    CD_STATUT,
    LB_ERREUR,
    DT_DEBUT,
    DT_FIN
)
VALUES
(
    @ID_TRT_ALI,
    @LB_PROJET,
    N'POSE BORNE',
    N'OIT_TEC_AUDIT_CDC',
    N'ORT_BORNE_JOURNEE',
    @nb_bornes,
    N'OK',

    CASE
        WHEN @nb_bornes = 0
        THEN
            N'IGNORE: extraction arretee au '
            + CONVERT(NVARCHAR(23), @fin_extraction, 121)
            + N'. Journee suivante non encore complete, frontiere : '
            + ISNULL
              (
                  CONVERT(NVARCHAR(23), @frontiere, 121),
                  N'inconnue'
              )
            + N'.'

        ELSE
            N'Extraction au '
            + CONVERT(NVARCHAR(23), @fin_extraction, 121)
            + N' : '
            + CONVERT(NVARCHAR(10), @nb_bornes)
            + N' journee(s) bornee(s) du '
            + CONVERT(NVARCHAR(10), @premiere, 23)
            + N' au '
            + CONVERT(NVARCHAR(10), @derniere, 23)
            + CASE
                WHEN @nb_bornes > 1
                    THEN N' (rattrapage).'
                ELSE N' (quotidien).'
              END
    END
    + CASE
        WHEN @nb_inst_absentes > 0
            THEN N' AVERTISSEMENT: ' + CONVERT(NVARCHAR(10), @nb_inst_absentes)
               + N' instance(s) DELTA sans ligne d''audit.'
        ELSE N''
      END,

    @dt_step,
    SYSDATETIME()
);

DECLARE @ID_TRT_ALI BIGINT       = <?=odiRef.getSession("SESS_NO") ?>;
DECLARE @LB_PROJET  NVARCHAR(50) = N'#INEO.V_NOM_PROJET';
DECLARE @LB_SCN     NVARCHAR(100) = N'<?=odiRef.getSession("SESS_NAME") ?>';

DECLARE @dt_step DATETIME = GETDATE(),
        @last_borne DATE, @deb_periode DATE, @fin_forcee DATE, @fin_retenue DATE;

/* Derniere journee bornee = derniere journee reellement traitable ------------ */
SELECT @last_borne = MAX(DT_JOUR)
FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
WHERE LB_PROJET=@LB_PROJET;

SELECT @deb_periode = CONVERT(date, DA_DEB_DEL_TRT, 121),
       @fin_forcee  = CONVERT(date, DA_FIN_DEL_FOR, 121)
FROM <?=odiRef.getObjectName("L", "PWTTRE", "MSSQL_DWH", "D") ?>
WHERE LB_NOM_SCN_SUN = @LB_SCN;

IF @deb_periode IS NULL
BEGIN
    DECLARE @msg NVARCHAR(500) =
        N'IWI.002 CADRAGE PERIODE : aucune ligne PWTTRE pour LB_NOM_SCN_SUN = '''
        + @LB_SCN + N''' - executer G_DWH_MEP/01_DWH_INIT_MEP.sql.';
    THROW 50023, @msg, 1;
END

/* Pas de borne -> periode vide (neutre) ; sinon min(forcage, derniere borne) - */
SET @fin_retenue = ISNULL(@last_borne, @deb_periode);

IF @fin_forcee IS NOT NULL AND @fin_forcee < @fin_retenue
    SET @fin_retenue = @fin_forcee;

UPDATE <?=odiRef.getObjectName("L", "PWTTRE", "MSSQL_DWH", "D") ?>
SET DA_FIN_DEL_FOR = @fin_retenue
WHERE LB_NOM_SCN_SUN = @LB_SCN;

INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
    (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
VALUES (@ID_TRT_ALI, @LB_PROJET, N'CADRAGE PERIODE',
        N'ORT_BORNE_JOURNEE', N'PWTTRE', 1, N'OK',
        N'Periode cadree : ] ' + CONVERT(NVARCHAR(10), @deb_periode, 23)
        + N' ; ' + CONVERT(NVARCHAR(10), @fin_retenue, 23) + N' ]'
        + CASE WHEN @last_borne IS NULL THEN N' - aucune borne posee, periode vide.'
               WHEN @fin_forcee IS NOT NULL AND @fin_forcee < @last_borne
                    THEN N' - reduite par forcage manuel DA_FIN_DEL_FOR.'
               ELSE N' - fin = derniere journee bornee.' END,
        @dt_step, GETDATE());

DECLARE @LB_PROJET NVARCHAR(50) = N'#INEO.V_NOM_PROJET';
INSERT INTO <?=odiRef.getObjectName("L", "ORT_PERIODE_REPRISE", "MSSQL_DWH", "D") ?> (LB_PROJET, DT_JOUR, NO_SEQ, FL_TRAITE, LB_NOM_SCN_SUN) SELECT @LB_PROJET, T.DT_JOUR, (ROW_NUMBER() OVER (ORDER BY T.DT_JOUR)) AS SEQ, 0 AS FL_TRAITE, '<?=odiRef.getSession("SESS_NAME") ?>' AS LB_NOM_SCN_SUN FROM ( /* Journees ouvrables de la periode cadree (quotidien). */ SELECT DISTINCT convert(date, DT_CAL, 121) as DT_JOUR FROM <?=odiRef.getObjectName("L", "PRTCAL", "MSSQL_DWH", "D") ?> WHERE FL_OVR = 1 AND convert(date, DT_CAL, 121) > (select convert(date, DA_DEB_DEL_TRT, 121) from <?=odiRef.getObjectName("L", "PWTTRE", "MSSQL_DWH", "D") ?> where LB_NOM_SCN_SUN = '<?=odiRef.getSession("SESS_NAME") ?>') and convert(date, DT_CAL, 121) <= (select convert(date, DA_DON_A_TRT, 121) from <?=odiRef.getObjectName("L", "PWTTRE", "MSSQL_DWH", "D") ?> where LB_NOM_SCN_SUN = '<?=odiRef.getSession("SESS_NAME") ?>')
UNION
/* Journées des bornes INIT non traitées : la date de reprise est libre, elles viennent directement de ORT_BORNE_JOURNEE. PWTTRE est clé par scénario, un scénario sert un projet : pas de filtre projet dessus. */ SELECT DISTINCT convert(date, B.DT_JOUR, 121) as DT_JOUR FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?> AS B WHERE B.LB_PROJET = @LB_PROJET AND B.TYPE_BORNE = N'INIT' AND B.FL_TRAITE = 0 ) AS T ORDER BY SEQ ASC

DECLARE @DT_TRACES  DATE          = '#INEO.V_IWI_LIGIS_DT_TRACES';
DECLARE @ID_TRT_ALI BIGINT        = <?=odiRef.getSession("SESS_NO") ?>;
DECLARE @LB_PROJET  NVARCHAR(50)  = N'#INEO.V_NOM_PROJET';
DECLARE @PFX_ODS NVARCHAR(300) =
    N'<?=odiRef.getCatalogName("MSSQL_ODS", "D") ?>.<?=odiRef.getSchemaName("MSSQL_ODS", "D") ?>.';

DECLARE @dt_deb DATETIME2(3), @dt_fin DATETIME2(3), @msg NVARCHAR(500),
        @jour NVARCHAR(10) = CONVERT(NVARCHAR(10), @DT_TRACES, 23),
        @fl_journee_init BIT = 0;

/* Journée d'initialisation : une borne INIT non traitée à cette date. */
IF EXISTS (SELECT 1 FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
           WHERE LB_PROJET = @LB_PROJET AND DT_JOUR = @DT_TRACES
             AND TYPE_BORNE = N'INIT' AND FL_TRAITE = 0)
    SET @fl_journee_init = 1;

/* Fenêtre : ] borne(J-1) ; borne(J) ], sans objet en journée INIT. */
IF @fl_journee_init = 0
BEGIN
    SELECT @dt_fin = DT_BORNE
    FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
    WHERE DT_JOUR = @DT_TRACES AND LB_PROJET = @LB_PROJET;

    SELECT @dt_deb = MAX(DT_BORNE)
    FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
    WHERE DT_JOUR < @DT_TRACES AND LB_PROJET = @LB_PROJET;

    IF @dt_fin IS NULL OR @dt_deb IS NULL
    BEGIN
        SET @msg = N'Fenêtre non définie pour le ' + @jour + N'.';
        THROW 50011, @msg, 1;
    END
END

DECLARE @tbl_ods NVARCHAR(128), @entree NVARCHAR(10),
        @cle NVARCHAR(MAX), @ordre NVARCHAR(MAX), @col_fen NVARCHAR(128),
        @filtre NVARCHAR(1000), @clause NVARCHAR(MAX), @src NVARCHAR(400),
        @sql NVARCHAR(MAX), @nb INT, @dt_step DATETIME2(3);

DECLARE cur_tables CURSOR LOCAL FAST_FORWARD FOR
    SELECT F.LB_TABLE_ODS, F.CD_MODE_ENTREE
    FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
    WHERE F.LB_PROJET = @LB_PROJET
      AND F.FL_ACTIF = 1
      AND F.CD_MODE_ALIM <> N'AUCUNE'
    ORDER BY F.NO_ORDRE, F.LB_TABLE_ODS;

OPEN cur_tables;
FETCH NEXT FROM cur_tables INTO @tbl_ods, @entree;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @dt_step = SYSDATETIME();
    SET @nb = 0;

    BEGIN TRY
        SET @src = @PFX_ODS + QUOTENAME(@tbl_ods);
        SELECT @cle = NULL, @ordre = NULL, @col_fen = NULL, @filtre = NULL;

        SELECT @cle = STRING_AGG(CONVERT(NVARCHAR(MAX), QUOTENAME(LB_CHAMP_ODS)), N',') WITHIN GROUP (ORDER BY NO_CHAMP)
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET = @LB_PROJET AND LB_TABLE_ODS = @tbl_ods AND FL_CLEF = 1 AND LB_CHAMP_ODS IS NOT NULL;

        SELECT @ordre = STRING_AGG(CONVERT(NVARCHAR(MAX), QUOTENAME(LB_CHAMP_ODS) + N' DESC'), N', ') WITHIN GROUP (ORDER BY NO_CHAMP)
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET = @LB_PROJET AND LB_TABLE_ODS = @tbl_ods AND FL_ORDRE_TRI = 1 AND LB_CHAMP_ODS IS NOT NULL;

        SELECT TOP (1) @col_fen = LB_CHAMP_ODS
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET = @LB_PROJET AND LB_TABLE_ODS = @tbl_ods AND FL_ORDRE_TRI = 1 AND LB_CHAMP_ODS IS NOT NULL
        ORDER BY NO_CHAMP;

        SELECT @filtre = ISNULL(F.LB_FILTRE_WHERE, N'')
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
        WHERE F.LB_PROJET = @LB_PROJET AND F.LB_TABLE_ODS = @tbl_ods;

        IF @cle IS NULL
        BEGIN
            SET @msg = N'Paramétrage incomplet pour ' + @tbl_ods + N' : aucune colonne clé.';
            THROW 50032, @msg, 1;
        END
        IF @col_fen IS NULL
        BEGIN
            SET @msg = N'Paramétrage incomplet pour ' + @tbl_ods + N' : aucune colonne FL_ORDRE_TRI.';
            THROW 50033, @msg, 1;
        END

        IF @fl_journee_init = 1
            SET @clause = CASE WHEN @filtre <> N'' THEN N' WHERE ' + @filtre ELSE N'' END;
        ELSE
            SET @clause = N' WHERE ' + QUOTENAME(@col_fen) + N' > @p_deb AND ' + QUOTENAME(@col_fen) + N' <= @p_fin'
                        + CASE WHEN @filtre <> N'' THEN N' AND ' + @filtre ELSE N'' END;

        /* Remise à zéro, idempotente. */
        SET @sql = N'UPDATE ' + @src + N' SET FL_FIN_JOURNEE = 0' + @clause + N';';
        EXEC sp_executesql @sql, N'@p_deb datetime2(3), @p_fin datetime2(3)',
             @p_deb = @dt_deb, @p_fin = @dt_fin;

        IF @entree = N'DELTA' OR @fl_journee_init = 1
            /* Dernière trace par clé. */
            SET @sql = N';WITH cte AS ('
                     + N'  SELECT FL_FIN_JOURNEE, ROW_NUMBER() OVER (PARTITION BY ' + @cle
                     + N'    ORDER BY ' + @ordre + N') AS rn_ort'
                     + N'  FROM ' + @src + @clause
                     + N') UPDATE cte SET FL_FIN_JOURNEE = 1 WHERE rn_ort = 1;'
                     + N' SELECT @p_nb = @@ROWCOUNT;';
        ELSE
            /* FULL : tout l'état livré dans la fenêtre. */
            SET @sql = N'UPDATE ' + @src + N' SET FL_FIN_JOURNEE = 1' + @clause + N';'
                     + N' SELECT @p_nb = @@ROWCOUNT;';

        EXEC sp_executesql @sql, N'@p_deb datetime2(3), @p_fin datetime2(3), @p_nb int OUTPUT',
             @p_deb = @dt_deb, @p_fin = @dt_fin, @p_nb = @nb OUTPUT;

        IF @nb = 0
            INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
                (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
            VALUES (@ID_TRT_ALI, @LB_PROJET, N'TRACES [' + @jour + N']', @tbl_ods, @tbl_ods, 0, N'OK',
                    N'AVERTISSEMENT: aucune ligne sur la fenêtre, cible non modifiée.', @dt_step, SYSDATETIME());
    END TRY
    BEGIN CATCH
        INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
            (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
        VALUES (@ID_TRT_ALI, @LB_PROJET, N'TRACES [' + @jour + N']', @tbl_ods, @tbl_ods, 0, N'KO',
                N'FLAG : ' + ERROR_MESSAGE(), @dt_step, SYSDATETIME());
    END CATCH

    FETCH NEXT FROM cur_tables INTO @tbl_ods, @entree;
END

CLOSE cur_tables;
DEALLOCATE cur_tables;

DECLARE @DT_TRACES    DATE         = '#INEO.V_IWI_LIGIS_DT_TRACES';
DECLARE @ID_TRT_ALI   BIGINT       = <?=odiRef.getSession("SESS_NO") ?>;
DECLARE @LB_PROJET    NVARCHAR(50) = N'#INEO.V_NOM_PROJET';
DECLARE @DATE_INFINIE DATE         = '2400-01-01';
DECLARE @PFX_DWH NVARCHAR(300) =
    N'<?=odiRef.getCatalogName("MSSQL_DWH", "D") ?>.<?=odiRef.getSchemaName("MSSQL_DWH", "D") ?>.';

DECLARE @jour NVARCHAR(10) = CONVERT(NVARCHAR(10), @DT_TRACES, 23),
        @tbl_ods NVARCHAR(128), @tbl_dwh NVARCHAR(200), @tgt NVARCHAR(400),
        @sql NVARCHAR(MAX), @msg NVARCHAR(2000),
        @nb_supp INT, @nb_rouv INT, @dt_step DATETIME2(3);

DECLARE cur_tables CURSOR LOCAL FAST_FORWARD FOR
    SELECT F.LB_TABLE_ODS, F.LB_TABLE_DWH
    FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
    WHERE F.LB_PROJET = @LB_PROJET
      AND F.FL_ACTIF = 1
      AND F.CD_MODE_ALIM IN (N'SCD2', N'AJOUT')
      AND F.LB_TABLE_DWH IS NOT NULL
      AND NOT EXISTS
      (
          SELECT 1
          FROM <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?> AS A
          WHERE A.ID_TRT_ALI = @ID_TRT_ALI
            AND A.LB_PROJET = @LB_PROJET
            AND A.CD_STATUT = N'KO'
            AND A.LB_SOURCE = F.LB_TABLE_ODS
            AND CHARINDEX(N'[' + @jour + N']', A.LB_CHARGEMENT) > 0
      )
    ORDER BY F.NO_ORDRE, F.LB_TABLE_ODS;

OPEN cur_tables;
FETCH NEXT FROM cur_tables INTO @tbl_ods, @tbl_dwh;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @dt_step = SYSDATETIME();
    SELECT @nb_supp = 0, @nb_rouv = 0;

    BEGIN TRY
        SET @tgt = @PFX_DWH + QUOTENAME(@tbl_dwh);

        BEGIN TRANSACTION;

        SET @sql = N'DELETE FROM ' + @tgt + N' WHERE DD_VAL >= @p_dt;'
                 + N' SELECT @p_nb = @@ROWCOUNT;';
        EXEC sp_executesql @sql, N'@p_dt date, @p_nb int OUTPUT',
             @p_dt = @DT_TRACES, @p_nb = @nb_supp OUTPUT;

        SET @sql = N'UPDATE ' + @tgt + N' SET DF_VAL = @p_infini, FL_VER_CRT = 1'
                 + N' WHERE DF_VAL = @p_dt AND FL_VER_CRT = 0;'
                 + N' SELECT @p_nb = @@ROWCOUNT;';
        EXEC sp_executesql @sql, N'@p_dt date, @p_infini date, @p_nb int OUTPUT',
             @p_dt = @DT_TRACES, @p_infini = @DATE_INFINIE, @p_nb = @nb_rouv OUTPUT;

        COMMIT TRANSACTION;

        IF @nb_supp > 0 OR @nb_rouv > 0
            INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
                (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
            VALUES (@ID_TRT_ALI, @LB_PROJET, N'RECALCUL [' + @jour + N']', @tbl_ods, @tbl_dwh, @nb_supp, N'OK',
                    N'Journée déjà traitée : ' + CONVERT(NVARCHAR(10), @nb_supp) + N' version(s) supprimée(s), '
                    + CONVERT(NVARCHAR(10), @nb_rouv) + N' rouverte(s) avant reconstruction.',
                    @dt_step, SYSDATETIME());
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @msg = N'PURGE OWT : ' + ERROR_MESSAGE()
                 + N' [erreur ' + CONVERT(NVARCHAR(20), ERROR_NUMBER())
                 + N', ligne ' + CONVERT(NVARCHAR(20), ERROR_LINE()) + N']';
        INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
            (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
        VALUES (@ID_TRT_ALI, @LB_PROJET, N'TRACES [' + @jour + N']', @tbl_ods, @tbl_dwh, 0, N'KO',
                @msg, @dt_step, SYSDATETIME());
    END CATCH

    FETCH NEXT FROM cur_tables INTO @tbl_ods, @tbl_dwh;
END

CLOSE cur_tables;
DEALLOCATE cur_tables;

DECLARE @DT_TRACES    DATE         = '#INEO.V_IWI_LIGIS_DT_TRACES';
DECLARE @ID_TRT_ALI   BIGINT       = <?=odiRef.getSession("SESS_NO") ?>;
DECLARE @LB_PROJET    NVARCHAR(50) = N'#INEO.V_NOM_PROJET';
DECLARE @DATE_INFINIE DATE         = '2400-01-01';
DECLARE @CD_USR_MAJ   NVARCHAR(20) = N'<?=odiRef.getSession("ODI_USER_NAME") ?>';
DECLARE @PFX_ODS NVARCHAR(300) = N'<?=odiRef.getCatalogName("MSSQL_ODS", "D") ?>.<?=odiRef.getSchemaName("MSSQL_ODS", "D") ?>.';
DECLARE @PFX_DWH NVARCHAR(300) = N'<?=odiRef.getCatalogName("MSSQL_DWH", "D") ?>.<?=odiRef.getSchemaName("MSSQL_DWH", "D") ?>.';

DECLARE @jour NVARCHAR(10) = CONVERT(NVARCHAR(10), @DT_TRACES, 23),
        @dt_deb DATETIME2(3), @dt_fin DATETIME2(3), @msg NVARCHAR(2000),
        @fl_journee_init BIT = 0;

IF EXISTS (SELECT 1 FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
           WHERE LB_PROJET = @LB_PROJET AND DT_JOUR = @DT_TRACES
             AND TYPE_BORNE = N'INIT' AND FL_TRAITE = 0)
    SET @fl_journee_init = 1;

IF @fl_journee_init = 0
BEGIN
    SELECT @dt_fin = DT_BORNE
    FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
    WHERE DT_JOUR = @DT_TRACES AND LB_PROJET = @LB_PROJET;

    SELECT @dt_deb = MAX(DT_BORNE)
    FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?>
    WHERE DT_JOUR < @DT_TRACES AND LB_PROJET = @LB_PROJET;

    IF @dt_fin IS NULL OR @dt_deb IS NULL
    BEGIN
        SET @msg = N'Fenêtre non définie pour le ' + @jour + N'.';
        THROW 50011, @msg, 1;
    END
END

DECLARE
    @tbl_ods   NVARCHAR(128), @tbl_dwh  NVARCHAR(200),
    @entree    NVARCHAR(10),  @alim     NVARCHAR(10), @img_complete BIT,
    @src NVARCHAR(400), @tgt NVARCHAR(400), @img NVARCHAR(MAX), @col_fen NVARCHAR(128),
    @cle1    NVARCHAR(128),      -- première colonne clé, nom ODS
    @join_st NVARCHAR(MAX),      -- S.[k] = T.[k]
    @join_mx NVARCHAR(MAX),      -- T2.[k] = S.[k]
    @join_tt NVARCHAR(MAX),      -- T3.[k] = T.[k]
    @cols    NVARCHAR(MAX),      -- [c]   colonnes copiées, clé incluse
    @vals_s  NVARCHAR(MAX),      -- S.[c]
    @vals_t  NVARCHAR(MAX),      -- T.[c]
    @set_s1  NVARCHAR(MAX),      -- T.[c] = S.[c]  hors clé
    @cmp_s   NVARCHAR(MAX), @cmp_t NVARCHAR(MAX),
    @sup_s   NVARCHAR(200),      -- FL_SUP porté par l'image
    @dml_s   NVARCHAR(200),      -- CD_DML_TEC porté par l'image
    @params  NVARCHAR(400) = N'@p_deb datetime2(3), @p_fin datetime2(3), @p_dt date, @p_inf date, @p_usr nvarchar(20), @p_trt bigint, @p_nb int OUTPUT',
    @sql NVARCHAR(MAX),
    @nb_img INT, @nb_ferm INT, @nb_ins INT, @nb_maj INT, @nb_sup INT, @dt_step DATETIME2(3);

DECLARE cur_tables CURSOR LOCAL FAST_FORWARD FOR
    SELECT F.LB_TABLE_ODS, F.LB_TABLE_DWH, F.CD_MODE_ENTREE, F.CD_MODE_ALIM
    FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
    WHERE F.LB_PROJET = @LB_PROJET
      AND F.FL_ACTIF = 1
      AND F.CD_MODE_ALIM <> N'AUCUNE'
      AND F.LB_TABLE_DWH IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?> AS A
                  WHERE A.ID_TRT_ALI = @ID_TRT_ALI
                    AND A.LB_PROJET = @LB_PROJET AND A.CD_STATUT = N'KO'
                    AND A.LB_SOURCE = F.LB_TABLE_ODS
                    AND CHARINDEX(N'[' + @jour + N']', A.LB_CHARGEMENT) > 0)
    ORDER BY F.NO_ORDRE, F.LB_TABLE_ODS;

OPEN cur_tables;
FETCH NEXT FROM cur_tables INTO @tbl_ods, @tbl_dwh, @entree, @alim;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @dt_step = SYSDATETIME();
    SELECT @nb_img = 0, @nb_ferm = 0, @nb_ins = 0, @nb_maj = 0, @nb_sup = 0;

    BEGIN TRY
        SET @src = @PFX_ODS + QUOTENAME(@tbl_ods);
        SET @tgt = @PFX_DWH + QUOTENAME(@tbl_dwh);
        SET @img_complete = CASE WHEN @entree = N'FULL' OR @fl_journee_init = 1 THEN 1 ELSE 0 END;
        SELECT @cle1=NULL,@col_fen=NULL,@join_st=NULL,@join_mx=NULL,@join_tt=NULL,
               @cols=NULL,@vals_s=NULL,@vals_t=NULL,@set_s1=NULL,@cmp_s=NULL,@cmp_t=NULL;

        /* Clé */
        SELECT
            @join_st = STRING_AGG(CONVERT(NVARCHAR(MAX), N'S.'+QUOTENAME(LB_CHAMP_ODS)+N' = T.'+QUOTENAME(LB_CHAMP_DWH)), N' AND ') WITHIN GROUP (ORDER BY NO_CHAMP),
            @join_mx = STRING_AGG(CONVERT(NVARCHAR(MAX), N'T2.'+QUOTENAME(LB_CHAMP_DWH)+N' = S.'+QUOTENAME(LB_CHAMP_ODS)), N' AND ') WITHIN GROUP (ORDER BY NO_CHAMP),
            @join_tt = STRING_AGG(CONVERT(NVARCHAR(MAX), N'T3.'+QUOTENAME(LB_CHAMP_DWH)+N' = T.'+QUOTENAME(LB_CHAMP_DWH)), N' AND ') WITHIN GROUP (ORDER BY NO_CHAMP)
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET=@LB_PROJET AND LB_TABLE_ODS=@tbl_ods AND FL_CLEF=1
          AND LB_CHAMP_ODS IS NOT NULL AND LB_CHAMP_DWH IS NOT NULL;

        SELECT TOP (1) @cle1 = LB_CHAMP_ODS
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET=@LB_PROJET AND LB_TABLE_ODS=@tbl_ods AND FL_CLEF=1
          AND LB_CHAMP_ODS IS NOT NULL AND LB_CHAMP_DWH IS NOT NULL
        ORDER BY NO_CHAMP;

        /* Colonne de fenêtre : première colonne d'ordre. */
        SELECT TOP (1) @col_fen = LB_CHAMP_ODS
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET=@LB_PROJET AND LB_TABLE_ODS=@tbl_ods AND FL_ORDRE_TRI=1 AND LB_CHAMP_ODS IS NOT NULL
        ORDER BY NO_CHAMP;

        /* Colonnes copiées */
        SELECT
            @cols   = STRING_AGG(CONVERT(NVARCHAR(MAX), QUOTENAME(LB_CHAMP_DWH)), N', ') WITHIN GROUP (ORDER BY NO_CHAMP),
            @vals_s = STRING_AGG(CONVERT(NVARCHAR(MAX), N'S.'+QUOTENAME(LB_CHAMP_ODS)), N', ') WITHIN GROUP (ORDER BY NO_CHAMP),
            @vals_t = STRING_AGG(CONVERT(NVARCHAR(MAX), N'T.'+QUOTENAME(LB_CHAMP_DWH)), N', ') WITHIN GROUP (ORDER BY NO_CHAMP)
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET=@LB_PROJET AND LB_TABLE_ODS=@tbl_ods AND FL_CHARGEMENT=1
          AND LB_CHAMP_ODS IS NOT NULL AND LB_CHAMP_DWH IS NOT NULL;

        /* Colonnes copiées hors clé : mise à jour SCD1 */
        SELECT
            @set_s1 = STRING_AGG(CONVERT(NVARCHAR(MAX), N'T.'+QUOTENAME(LB_CHAMP_DWH)+N' = S.'+QUOTENAME(LB_CHAMP_ODS)), N', ') WITHIN GROUP (ORDER BY NO_CHAMP)
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET=@LB_PROJET AND LB_TABLE_ODS=@tbl_ods AND FL_CHARGEMENT=1 AND FL_CLEF=0
          AND LB_CHAMP_ODS IS NOT NULL AND LB_CHAMP_DWH IS NOT NULL;

        /* Colonnes comparées : hors clé, hors ordre */
        SELECT
            @cmp_s  = STRING_AGG(CONVERT(NVARCHAR(MAX), N'ISNULL(CONVERT(NVARCHAR(MAX), S.'+QUOTENAME(LB_CHAMP_ODS)+N'), N''<null>'')'), N' + N''|'' + ') WITHIN GROUP (ORDER BY NO_CHAMP),
            @cmp_t  = STRING_AGG(CONVERT(NVARCHAR(MAX), N'ISNULL(CONVERT(NVARCHAR(MAX), T.'+QUOTENAME(LB_CHAMP_DWH)+N'), N''<null>'')'), N' + N''|'' + ') WITHIN GROUP (ORDER BY NO_CHAMP)
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
        WHERE LB_PROJET=@LB_PROJET AND LB_TABLE_ODS=@tbl_ods AND FL_CHARGEMENT=1 AND FL_CLEF=0 AND FL_ORDRE_TRI=0
          AND LB_CHAMP_ODS IS NOT NULL AND LB_CHAMP_DWH IS NOT NULL;

        SET @cmp_s = ISNULL(@cmp_s, N'N''''');
        SET @cmp_t = ISNULL(@cmp_t, N'N''''');

        /* Sens de la modification : porté par CD_DML_TEC quand le sas la
           déclare (traces CDC, y compris en journée INIT), sinon insertion. */
        IF @entree = N'DELTA' AND EXISTS
        (
            SELECT 1 FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?>
            WHERE LB_PROJET=@LB_PROJET AND LB_TABLE_ODS=@tbl_ods AND LB_CHAMP_ODS = N'CD_DML_TEC'
        )
            SELECT @sup_s = N'CASE WHEN S.[CD_DML_TEC] = 1 THEN 1 ELSE 0 END', @dml_s = N'S.[CD_DML_TEC]';
        ELSE
            SELECT @sup_s = N'0', @dml_s = N'NULL';

        IF @join_st IS NULL OR @cols IS NULL OR @col_fen IS NULL
        BEGIN
            SET @msg = N'Paramétrage incomplet pour ' + @tbl_ods + N' (clé, colonnes ou colonne d''ordre).';
            THROW 50042, @msg, 1;
        END

        /* L'image : flags de la fenêtre, ou tout le sas flagué en journée INIT. */
        SET @img = N'(SELECT * FROM ' + @src + N' WHERE FL_FIN_JOURNEE = 1'
                 + CASE WHEN @fl_journee_init = 1 THEN N''
                        ELSE N' AND ' + QUOTENAME(@col_fen) + N' > @p_deb AND ' + QUOTENAME(@col_fen) + N' <= @p_fin' END
                 + N')';

        SET @sql = N'SELECT @p_nb = COUNT(*) FROM ' + @img + N' AS S;';
        EXEC sp_executesql @sql, @params,
             @p_deb=@dt_deb, @p_fin=@dt_fin, @p_dt=@DT_TRACES, @p_inf=@DATE_INFINIE, @p_usr=@CD_USR_MAJ, @p_trt=@ID_TRT_ALI, @p_nb=@nb_img OUTPUT;

        /* Image vide : rien à reporter. Pour une image complète, ce n'est pas
           "tout a été supprimé" mais "rien n'a été livré". */
        IF @nb_img = 0
        BEGIN
            INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
                (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
            VALUES (@ID_TRT_ALI, @LB_PROJET, N'TRACES [' + @jour + N']', @tbl_ods, @tbl_dwh, 0, N'OK',
                    @entree + N' / ' + @alim + N' - image vide, cible non modifiée.', @dt_step, SYSDATETIME());
        END
        ELSE
        BEGIN
            BEGIN TRANSACTION;

            IF @alim = N'SCD2'
            BEGIN
                IF @img_complete = 0
                    /* Image partielle : clés de l'image dont la valeur ou le sens change. */
                    SET @sql = N'UPDATE T SET T.DF_VAL = @p_dt, T.FL_VER_CRT = 0'
                             + N' FROM ' + @tgt + N' AS T'
                             + N' INNER JOIN ' + @img + N' AS S ON ' + @join_st
                             + N' WHERE T.FL_VER_CRT = 1'
                             + N'   AND (' + @cmp_t + N' <> ' + @cmp_s + N' OR T.FL_SUP <> ' + @sup_s + N');'
                             + N' SELECT @p_nb = @@ROWCOUNT;';
                ELSE
                    /* Image complète : clé disparue (encore vivante), ou présente et
                       différente, ou présente avec un autre sens. Une clé déjà
                       supprimée et toujours absente n'est pas touchée. */
                    SET @sql = N'UPDATE T SET T.DF_VAL = @p_dt, T.FL_VER_CRT = 0'
                             + N' FROM ' + @tgt + N' AS T'
                             + N' LEFT JOIN ' + @img + N' AS S ON ' + @join_st
                             + N' WHERE T.FL_VER_CRT = 1'
                             + N'   AND ((S.' + QUOTENAME(@cle1) + N' IS NULL AND T.FL_SUP = 0)'
                             + N'     OR (S.' + QUOTENAME(@cle1) + N' IS NOT NULL'
                             + N'         AND (' + @cmp_t + N' <> ' + @cmp_s + N' OR T.FL_SUP <> ' + @sup_s + N')));'
                             + N' SELECT @p_nb = @@ROWCOUNT;';
                EXEC sp_executesql @sql, @params,
                     @p_deb=@dt_deb, @p_fin=@dt_fin, @p_dt=@DT_TRACES, @p_inf=@DATE_INFINIE, @p_usr=@CD_USR_MAJ, @p_trt=@ID_TRT_ALI, @p_nb=@nb_ferm OUTPUT;

                /* Insertion des clés de l'image sans version courante. */
                SET @sql = N'INSERT INTO ' + @tgt + N' (' + @cols
                         + N', NO_SEQ, DD_VAL, DF_VAL, FL_SUP, FL_VER_CRT, CD_DML_TEC, DT_MAJ_TRT, CD_USR_MAJ, ID_TRT_ALI)'
                         + N' SELECT ' + @vals_s
                         + N', ISNULL((SELECT MAX(T2.NO_SEQ) FROM ' + @tgt + N' AS T2 WHERE ' + @join_mx + N'), 0) + 1'
                         + N', @p_dt, @p_inf, ' + @sup_s + N', 1, ' + @dml_s + N', SYSDATETIME(), @p_usr, @p_trt'
                         + N' FROM ' + @img + N' AS S'
                         + N' WHERE NOT EXISTS (SELECT 1 FROM ' + @tgt + N' AS T WHERE ' + @join_st + N' AND T.FL_VER_CRT = 1);'
                         + N' SELECT @p_nb = @@ROWCOUNT;';
                EXEC sp_executesql @sql, @params,
                     @p_deb=@dt_deb, @p_fin=@dt_fin, @p_dt=@DT_TRACES, @p_inf=@DATE_INFINIE, @p_usr=@CD_USR_MAJ, @p_trt=@ID_TRT_ALI, @p_nb=@nb_ins OUTPUT;

                /* Image complète : clés disparues -> version FL_SUP = 1. */
                IF @img_complete = 1
                BEGIN
                    SET @sql = N'INSERT INTO ' + @tgt + N' (' + @cols
                             + N', NO_SEQ, DD_VAL, DF_VAL, FL_SUP, FL_VER_CRT, CD_DML_TEC, DT_MAJ_TRT, CD_USR_MAJ, ID_TRT_ALI)'
                             + N' SELECT ' + @vals_t
                             + N', T.NO_SEQ + 1, @p_dt, @p_inf, 1, 1, 1, SYSDATETIME(), @p_usr, @p_trt'
                             + N' FROM ' + @tgt + N' AS T'
                             + N' WHERE T.DF_VAL = @p_dt AND T.FL_VER_CRT = 0 AND T.FL_SUP = 0'
                             + N'   AND NOT EXISTS (SELECT 1 FROM ' + @img + N' AS S WHERE ' + @join_st + N')'
                             + N'   AND NOT EXISTS (SELECT 1 FROM ' + @tgt + N' AS T3 WHERE ' + @join_tt + N' AND T3.FL_VER_CRT = 1);'
                             + N' SELECT @p_nb = @@ROWCOUNT;';
                    EXEC sp_executesql @sql, @params,
                         @p_deb=@dt_deb, @p_fin=@dt_fin, @p_dt=@DT_TRACES, @p_inf=@DATE_INFINIE, @p_usr=@CD_USR_MAJ, @p_trt=@ID_TRT_ALI, @p_nb=@nb_sup OUTPUT;
                END
            END
            ELSE IF @alim = N'SCD1'
            BEGIN
                SET @sql = N'MERGE ' + @tgt + N' AS T USING ' + @img + N' AS S ON ' + @join_st
                         + N' WHEN MATCHED AND (' + @cmp_t + N' <> ' + @cmp_s + N' OR T.FL_SUP <> ' + @sup_s + N')'
                         + N' THEN UPDATE SET '
                         + CASE WHEN @set_s1 IS NOT NULL THEN @set_s1 + N', ' ELSE N'' END
                         + N'T.FL_SUP = ' + @sup_s + N', T.CD_DML_TEC = ' + @dml_s
                         + N', T.NO_SEQ = T.NO_SEQ + 1, T.DT_MAJ_TRT = SYSDATETIME(), T.CD_USR_MAJ = @p_usr, T.ID_TRT_ALI = @p_trt'
                         + N' WHEN NOT MATCHED BY TARGET THEN INSERT (' + @cols
                         + N', NO_SEQ, DD_VAL, DF_VAL, FL_SUP, FL_VER_CRT, CD_DML_TEC, DT_MAJ_TRT, CD_USR_MAJ, ID_TRT_ALI)'
                         + N' VALUES (' + @vals_s + N', 1, @p_dt, @p_inf, ' + @sup_s + N', 1, ' + @dml_s + N', SYSDATETIME(), @p_usr, @p_trt)'
                         + CASE WHEN @img_complete = 1
                                THEN N' WHEN NOT MATCHED BY SOURCE AND T.FL_SUP = 0 THEN UPDATE SET T.FL_SUP = 1, T.CD_DML_TEC = 1, T.NO_SEQ = T.NO_SEQ + 1, T.DT_MAJ_TRT = SYSDATETIME(), T.CD_USR_MAJ = @p_usr, T.ID_TRT_ALI = @p_trt'
                                ELSE N'' END
                         + N'; SELECT @p_nb = @@ROWCOUNT;';
                EXEC sp_executesql @sql, @params,
                     @p_deb=@dt_deb, @p_fin=@dt_fin, @p_dt=@DT_TRACES, @p_inf=@DATE_INFINIE, @p_usr=@CD_USR_MAJ, @p_trt=@ID_TRT_ALI, @p_nb=@nb_maj OUTPUT;
            END
            ELSE IF @alim = N'AJOUT'
            BEGIN
                SET @sql = N'INSERT INTO ' + @tgt + N' (' + @cols
                         + N', NO_SEQ, DD_VAL, DF_VAL, FL_SUP, FL_VER_CRT, CD_DML_TEC, DT_MAJ_TRT, CD_USR_MAJ, ID_TRT_ALI)'
                         + N' SELECT ' + @vals_s
                         + N', ISNULL((SELECT MAX(T2.NO_SEQ) FROM ' + @tgt + N' AS T2 WHERE ' + @join_mx + N'), 0) + 1'
                         + N', @p_dt, @p_inf, ' + @sup_s + N', 1, ' + @dml_s + N', SYSDATETIME(), @p_usr, @p_trt'
                         + N' FROM ' + @img + N' AS S; SELECT @p_nb = @@ROWCOUNT;';
                EXEC sp_executesql @sql, @params,
                     @p_deb=@dt_deb, @p_fin=@dt_fin, @p_dt=@DT_TRACES, @p_inf=@DATE_INFINIE, @p_usr=@CD_USR_MAJ, @p_trt=@ID_TRT_ALI, @p_nb=@nb_ins OUTPUT;
            END

            COMMIT TRANSACTION;

            INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
                (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
            VALUES (@ID_TRT_ALI, @LB_PROJET, N'TRACES [' + @jour + N']', @tbl_ods, @tbl_dwh,
                    CASE WHEN @alim = N'SCD1' THEN @nb_maj ELSE @nb_ins + @nb_sup END, N'OK',
                    @entree + N' / ' + @alim + CASE WHEN @fl_journee_init = 1 THEN N' (INIT)' ELSE N'' END
                    + N' - image: ' + CONVERT(NVARCHAR(10), @nb_img)
                    + CASE WHEN @alim = N'SCD2' THEN N' / fermées: ' + CONVERT(NVARCHAR(10),@nb_ferm) + N' / insérées: ' + CONVERT(NVARCHAR(10),@nb_ins)
                                                     + CASE WHEN @nb_sup > 0 THEN N' / supprimées: ' + CONVERT(NVARCHAR(10),@nb_sup) ELSE N'' END
                           WHEN @alim = N'SCD1' THEN N' / lignes touchées: ' + CONVERT(NVARCHAR(10),@nb_maj)
                           ELSE N' / insérées: ' + CONVERT(NVARCHAR(10),@nb_ins) END,
                    @dt_step, SYSDATETIME());
        END
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
            (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
        VALUES (@ID_TRT_ALI, @LB_PROJET, N'TRACES [' + @jour + N']', @tbl_ods, @tbl_dwh, 0, N'KO',
                N'HISTO ' + ISNULL(@alim, N'?') + N' : ' + ERROR_MESSAGE(), @dt_step, SYSDATETIME());
    END CATCH

    FETCH NEXT FROM cur_tables INTO @tbl_ods, @tbl_dwh, @entree, @alim;
END

CLOSE cur_tables;
DEALLOCATE cur_tables;

DECLARE @DT_TRACES  DATE          = '#INEO.V_IWI_LIGIS_DT_TRACES';
DECLARE @ID_TRT_ALI BIGINT        = <?=odiRef.getSession("SESS_NO") ?>;
DECLARE @LB_PROJET  NVARCHAR(50)  = N'#INEO.V_NOM_PROJET';


DECLARE @jour NVARCHAR(10) = CONVERT(NVARCHAR(10), @DT_TRACES, 23),
        @msg NVARCHAR(500), @dt_deb_bilan DATETIME = GETDATE(),
        @nb_ok INT, @nb_ko INT, @nb_tbl_ko INT;

/* 1. Bilan de la journee ----------------------------------------------------- */
SELECT @nb_ok = SUM(CASE WHEN CD_STATUT = 'OK' THEN 1 ELSE 0 END),
       @nb_ko = SUM(CASE WHEN CD_STATUT = 'KO' THEN 1 ELSE 0 END)
FROM <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
WHERE ISNULL(ID_TRT_ALI, -1) = ISNULL(@ID_TRT_ALI, -1)
  AND LB_PROJET = @LB_PROJET
  AND CHARINDEX('[' + @jour + ']', LB_CHARGEMENT) > 0
  AND LB_SOURCE <> '*TOUTES*';

SELECT @nb_tbl_ko = COUNT(DISTINCT LB_SOURCE)
FROM <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
WHERE ISNULL(ID_TRT_ALI, -1) = ISNULL(@ID_TRT_ALI, -1)
  AND LB_PROJET = @LB_PROJET
  AND CD_STATUT = 'KO'
  AND CHARINDEX('[' + @jour + ']', LB_CHARGEMENT) > 0
  AND LB_SOURCE <> '*TOUTES*';

SET @nb_ok     = ISNULL(@nb_ok, 0);
SET @nb_ko     = ISNULL(@nb_ko, 0);
SET @nb_tbl_ko = ISNULL(@nb_tbl_ko, 0);

INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
    (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
VALUES (@ID_TRT_ALI, @LB_PROJET, N'BILAN JOURNEE [' + @jour + N']',
        N'*TOUTES*', NULL, @nb_ok,
        CASE WHEN @nb_ko > 0 THEN N'KO' ELSE N'OK' END,
        CASE WHEN @nb_ko > 0
             THEN CAST(@nb_tbl_ko AS NVARCHAR(10)) + N' table(s) en KO sur la journee.'
             ELSE NULL END,
        @dt_deb_bilan, GETDATE());

/* 2. Remontee d'erreur a ODI ------------------------------------------------- */
IF @nb_ko > 0
BEGIN
    SET @msg = N'IWI.007 BILAN JOURNEE : ' + CAST(@nb_tbl_ko AS NVARCHAR(10))
             + N' table(s) en KO pour la journee ' + @jour
             + N'. Detail dans ORT_AUDIT_CHARGEMENT (LB_PROJET = '+@LB_PROJET+').';
    THROW 50010, @msg, 1;
END

DECLARE @ID_TRT_ALI BIGINT = <?=odiRef.getSession("SESS_NO") ?>; DECLARE @LB_PROJET NVARCHAR(50) = N'#INEO.V_NOM_PROJET'; DECLARE @CD_USR_MAJ NVARCHAR(20) = N'<?=odiRef.getSession("ODI_USER_NAME") ?>';
DECLARE @dt_step DATETIME2(3) = SYSDATETIME(), @dt_jour DATE, @nb_ins BIGINT = 0, @nb_total BIGINT = 0, @nb_sans_lsn BIGINT = 0, @message NVARCHAR(2000);
SELECT @dt_jour = MAX(CONVERT(DATE, B.DT_JOUR, 121)) FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?> AS B WHERE B.LB_PROJET = @LB_PROJET;
/* Aucune journée bornée : aucun archivage */
IF @dt_jour IS NULL BEGIN INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?> ( ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN ) VALUES ( @ID_TRT_ALI, @LB_PROJET, N'ARCHIVE AUDIT CDC', N'OIT_TEC_AUDIT_CDC', N'OWT_TEC_AUDIT_CDC', 0, N'OK', N'IGNORE: aucune journee bornee pour le projet ' + @LB_PROJET + N'. Aucun audit CDC archive.', @dt_step, SYSDATETIME() );
RETURN; END;
SELECT @nb_total = COUNT_BIG(*),
@nb_sans_lsn = ISNULL( SUM( CASE WHEN A.LB_FIN_LSN IS NULL THEN 1 ELSE 0 END ), 0 ) FROM <?=odiRef.getObjectName("L", "OIT_TEC_AUDIT_CDC", "MSSQL_ODS", "D") ?> AS A;
BEGIN TRY INSERT INTO <?=odiRef.getObjectName("L", "OWT_TEC_AUDIT_CDC", "MSSQL_DWH", "D") ?> ( LB_PROJET, NO_SEQUENCE, LB_INSTANCE, DT_JOUR_TEC, DT_DEB_LSN, DT_FIN_LSN, DT_EXTRACT, ID_INSTANCE, LB_DEB_LSN, LB_FIN_LSN, DT_MAJ_TRT, CD_USR_MAJ, ID_TRT_ALI ) SELECT @LB_PROJET, A.NO_SEQUENCE, A.LB_INSTANCE, @dt_jour, A.DT_DEB_LSN, A.DT_FIN_LSN, A.DT_EXTRACT, A.ID_INSTANCE, A.LB_DEB_LSN, A.LB_FIN_LSN, SYSDATETIME(), @CD_USR_MAJ, @ID_TRT_ALI FROM <?=odiRef.getObjectName("L", "OIT_TEC_AUDIT_CDC", "MSSQL_ODS", "D") ?> AS A WHERE A.LB_FIN_LSN IS NOT NULL AND A.LB_INSTANCE IN ( SELECT F.LB_SOURCE FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F WHERE F.LB_PROJET = @LB_PROJET AND F.LB_SOURCE IS NOT NULL ) AND NOT EXISTS ( SELECT 1 FROM <?=odiRef.getObjectName("L", "OWT_TEC_AUDIT_CDC", "MSSQL_DWH", "D") ?> AS H WHERE H.LB_PROJET = @LB_PROJET AND H.LB_INSTANCE = A.LB_INSTANCE AND H.NO_SEQUENCE = A.NO_SEQUENCE );
SET @nb_ins = @@ROWCOUNT;
SET @message = CASE WHEN @nb_total = 0 THEN N'AVERTISSEMENT: OIT_TEC_AUDIT_CDC est vide. ' + N'Verifier le BCP IN de la vue d''audit.'
WHEN @nb_sans_lsn > 0 THEN N'AVERTISSEMENT: ' + CONVERT(NVARCHAR(20), @nb_sans_lsn) + N' ligne(s) ecartee(s) faute de LB_FIN_LSN sur ' + CONVERT(NVARCHAR(20), @nb_total) + N' ligne(s) presente(s).'
WHEN @nb_ins = 0 THEN N'IGNORE: aucune nouvelle extraction CDC ' + N'depuis le dernier archivage.'
ELSE N'Extractions CDC archivees : ' + CONVERT(NVARCHAR(20), @nb_ins) + N' sur ' + CONVERT(NVARCHAR(20), @nb_total) + N' ligne(s) presente(s).' END;
INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?> ( ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN ) VALUES ( @ID_TRT_ALI, @LB_PROJET, N'ARCHIVE AUDIT CDC [' + CONVERT(NVARCHAR(10), @dt_jour, 23) + N']', N'OIT_TEC_AUDIT_CDC', N'OWT_TEC_AUDIT_CDC', @nb_ins, N'OK', @message, @dt_step, SYSDATETIME() ); END TRY BEGIN CATCH SET @message = N'ARCHIVE AUDIT CDC : ' + ERROR_MESSAGE() + N' [erreur ' + CONVERT(NVARCHAR(20), ERROR_NUMBER()) + N', ligne ' + CONVERT(NVARCHAR(20), ERROR_LINE()) + N']';
INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?> ( ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN ) VALUES ( @ID_TRT_ALI, @LB_PROJET, N'ARCHIVE AUDIT CDC', N'OIT_TEC_AUDIT_CDC', N'OWT_TEC_AUDIT_CDC', 0, N'KO', @message, @dt_step, SYSDATETIME() );
THROW; END CATCH;

DECLARE @ID_TRT_ALI BIGINT = <?=odiRef.getSession("SESS_NO") ?>;
DECLARE @LB_PROJET NVARCHAR(50) = N'#INEO.V_NOM_PROJET';
DECLARE @CD_USR_MAJ NVARCHAR(20) = N'<?=odiRef.getSession("ODI_USER_NAME") ?>';

DECLARE @PFX_ODS NVARCHAR(300) =
    N'<?=odiRef.getCatalogName("MSSQL_ODS", "D") ?>.<?=odiRef.getSchemaName("MSSQL_ODS", "D") ?>.';
DECLARE @PFX_HISTO NVARCHAR(300) =
    N'<?=odiRef.getCatalogName("MSSQL_ODS_TRACES", "D") ?>.<?=odiRef.getSchemaName("MSSQL_ODS_TRACES", "D") ?>.';

DECLARE
    @jour_max  DATE,
    @fin       DATETIME2(3),
    @msg       NVARCHAR(2000),
    @nb_ko     INT = 0,
    @dt_step   DATETIME2(3);

/* Dernière journée traitée par cette exécution (FL_TRAITE posé par 008). */
SELECT @jour_max = MAX(P.DT_JOUR)
FROM <?=odiRef.getObjectName("L", "ORT_PERIODE_REPRISE", "MSSQL_DWH", "D") ?> AS P
WHERE P.LB_NOM_SCN_SUN = '<?=odiRef.getSession("SESS_NAME") ?>'
  AND P.LB_PROJET = @LB_PROJET
  AND P.FL_TRAITE = 1;

SELECT @fin = B.DT_BORNE
FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?> AS B
WHERE B.LB_PROJET = @LB_PROJET AND B.DT_JOUR = @jour_max;

IF @jour_max IS NULL OR @fin IS NULL
BEGIN
    INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
        (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
    VALUES (@ID_TRT_ALI, @LB_PROJET, N'ARCHIVE OIT', N'*TOUTES*', NULL, 0, N'OK',
            CASE WHEN @jour_max IS NULL
                 THEN N'IGNORE: aucune journée traitée par cette exécution, rien à archiver.'
                 ELSE N'IGNORE: borne absente pour la journée ' + CONVERT(NVARCHAR(10), @jour_max, 23) + N', rien à archiver.' END,
            SYSDATETIME(), SYSDATETIME());
    RETURN;
END;

DECLARE
    @tbl_ods    NVARCHAR(128), @tbl_histo NVARCHAR(200),
    @src        NVARCHAR(400), @tgt       NVARCHAR(400),
    @col_fen    NVARCHAR(128), @retention INT, @limite DATETIME2(3),
    @cols       NVARCHAR(MAX), @cols_src  NVARCHAR(MAX),
    @fenetre    NVARCHAR(400), @jour_expr NVARCHAR(MAX),
    @sql        NVARCHAR(MAX),
    @nb_a_traiter BIGINT, @nb_supp_histo BIGINT, @nb_ins_histo BIGINT,
    @nb_absentes BIGINT, @nb_non_conformes BIGINT, @nb_purgees BIGINT;

DECLARE cur_tables CURSOR LOCAL FAST_FORWARD FOR
    SELECT F.LB_TABLE_ODS, F.NB_MOIS_RETENTION
    FROM <?=odiRef.getObjectName("L", "ORT_PARAM_FLUX", "MSSQL_DWH", "D") ?> AS F
    WHERE F.LB_PROJET = @LB_PROJET
      AND F.FL_ACTIF = 1
      AND F.CD_MODE_ENTREE = N'DELTA'
    ORDER BY F.NO_ORDRE, F.LB_TABLE_ODS;

OPEN cur_tables;
FETCH NEXT FROM cur_tables INTO @tbl_ods, @retention;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @dt_step = SYSDATETIME();
    SET @tbl_histo = @tbl_ods + N'_HISTO';
    SET @src = @PFX_ODS + QUOTENAME(@tbl_ods);
    SET @tgt = @PFX_HISTO + QUOTENAME(@tbl_histo);
    SELECT @cols = NULL, @cols_src = NULL, @col_fen = NULL,
           @nb_a_traiter = 0, @nb_supp_histo = 0, @nb_ins_histo = 0,
           @nb_absentes = 0, @nb_non_conformes = 0, @nb_purgees = 0;

    BEGIN TRY
        /* Colonnes du sas : toutes celles avec LB_CHAMP_ODS renseigné. */
        SELECT
            @cols     = STRING_AGG(CONVERT(NVARCHAR(MAX), QUOTENAME(P.LB_CHAMP_ODS)), N', ') WITHIN GROUP (ORDER BY P.NO_CHAMP),
            @cols_src = STRING_AGG(CONVERT(NVARCHAR(MAX), N'S.' + QUOTENAME(P.LB_CHAMP_ODS)), N', ') WITHIN GROUP (ORDER BY P.NO_CHAMP)
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?> AS P
        WHERE P.LB_PROJET = @LB_PROJET AND P.LB_TABLE_ODS = @tbl_ods AND P.LB_CHAMP_ODS IS NOT NULL;

        SELECT TOP (1) @col_fen = P.LB_CHAMP_ODS
        FROM <?=odiRef.getObjectName("L", "ORT_PARAM_HISTORISATION_TRACES", "MSSQL_DWH", "D") ?> AS P
        WHERE P.LB_PROJET = @LB_PROJET AND P.LB_TABLE_ODS = @tbl_ods
          AND P.FL_ORDRE_TRI = 1 AND P.LB_CHAMP_ODS IS NOT NULL
        ORDER BY P.NO_CHAMP;

        IF @cols IS NULL OR @col_fen IS NULL
        BEGIN
            SET @msg = N'Paramétrage incomplet pour ' + @tbl_ods + N' : colonnes ou colonne d''ordre absentes.';
            THROW 50040, @msg, 1;
        END;

        /* Traces à archiver : datées au plus tard de la frontière, pas encore
           dans l'archive ou archivées avec une autre image. */
        SET @fenetre = N' S.' + QUOTENAME(@col_fen) + N' <= @p_fin'
                     + N' AND NOT EXISTS (SELECT 1 FROM ' + @tgt + N' AS HX'
                     + N'   WHERE HX.LB_LSN_COMMIT_TEC = S.LB_LSN_COMMIT_TEC AND HX.LB_SEQVAL_TEC = S.LB_SEQVAL_TEC'
                     + N'     AND ISNULL(HX.FL_FIN_JOURNEE, 0) = ISNULL(S.FL_FIN_JOURNEE, 0))';

        /* Journée de rattachement : première borne >= date de la trace. */
        SET @jour_expr =
              N'(SELECT TOP (1) B.DT_JOUR'
            + N' FROM <?=odiRef.getObjectName("L", "ORT_BORNE_JOURNEE", "MSSQL_DWH", "D") ?> AS B'
            + N' WHERE B.LB_PROJET = @p_projet AND B.DT_BORNE >= S.' + QUOTENAME(@col_fen)
            + N' ORDER BY B.DT_BORNE)';

        SET @sql = N'SELECT @p_nb = COUNT_BIG(*) FROM ' + @src + N' AS S WHERE' + @fenetre + N';';
        EXEC sp_executesql @sql, N'@p_fin datetime2(3), @p_nb bigint OUTPUT',
             @p_fin = @fin, @p_nb = @nb_a_traiter OUTPUT;

        BEGIN TRANSACTION;

        IF @nb_a_traiter > 0
        BEGIN
            /* 1. Anciennes images de ces traces. */
            SET @sql = N'DELETE H FROM ' + @tgt + N' AS H'
                     + N' INNER JOIN ' + @src + N' AS S'
                     + N'    ON H.LB_LSN_COMMIT_TEC = S.LB_LSN_COMMIT_TEC AND H.LB_SEQVAL_TEC = S.LB_SEQVAL_TEC'
                     + N' WHERE' + @fenetre + N';'
                     + N' SELECT @p_nb = @@ROWCOUNT;';
            EXEC sp_executesql @sql, N'@p_fin datetime2(3), @p_nb bigint OUTPUT',
                 @p_fin = @fin, @p_nb = @nb_supp_histo OUTPUT;

            /* 2. Copie. */
            SET @sql = N'INSERT INTO ' + @tgt + N' (' + @cols + N', DT_JOUR_TEC, DT_MAJ_TRT, CD_USR_MAJ, ID_TRT_ALI)'
                     + N' SELECT ' + @cols_src + N', ' + @jour_expr + N', SYSDATETIME(), @p_usr, @p_trt'
                     + N' FROM ' + @src + N' AS S WHERE' + @fenetre + N';'
                     + N' SELECT @p_nb = @@ROWCOUNT;';
            EXEC sp_executesql @sql,
                 N'@p_fin datetime2(3), @p_projet nvarchar(50), @p_usr nvarchar(20), @p_trt bigint, @p_nb bigint OUTPUT',
                 @p_fin = @fin, @p_projet = @LB_PROJET, @p_usr = @CD_USR_MAJ, @p_trt = @ID_TRT_ALI, @p_nb = @nb_ins_histo OUTPUT;

            IF @nb_ins_histo <> @nb_a_traiter
            BEGIN
                SET @msg = N'Volumétrie incohérente pour ' + @tbl_histo + N' : '
                         + CONVERT(NVARCHAR(20), @nb_a_traiter) + N' attendue(s), '
                         + CONVERT(NVARCHAR(20), @nb_ins_histo) + N' réinsérée(s).';
                THROW 50041, @msg, 1;
            END;

            /* 3. Chaque trace datée jusqu'à la frontière est dans l'archive. */
            SET @sql = N'SELECT @p_nb = COUNT_BIG(*) FROM ' + @src + N' AS S WHERE S.' + QUOTENAME(@col_fen) + N' <= @p_fin'
                     + N' AND NOT EXISTS (SELECT 1 FROM ' + @tgt + N' AS H'
                     + N'   WHERE H.LB_LSN_COMMIT_TEC = S.LB_LSN_COMMIT_TEC AND H.LB_SEQVAL_TEC = S.LB_SEQVAL_TEC);';
            EXEC sp_executesql @sql, N'@p_fin datetime2(3), @p_nb bigint OUTPUT',
                 @p_fin = @fin, @p_nb = @nb_absentes OUTPUT;

            IF @nb_absentes > 0
            BEGIN
                SET @msg = N'Réinsertion incomplète vers ' + @tbl_histo + N' : '
                         + CONVERT(NVARCHAR(20), @nb_absentes) + N' trace(s) absente(s).';
                THROW 50042, @msg, 1;
            END;

            /* 4. L'image archivée est celle du sas. */
            SET @sql = N'SELECT @p_nb = COUNT_BIG(*) FROM ' + @src + N' AS S'
                     + N' INNER JOIN ' + @tgt + N' AS H'
                     + N'    ON H.LB_LSN_COMMIT_TEC = S.LB_LSN_COMMIT_TEC AND H.LB_SEQVAL_TEC = S.LB_SEQVAL_TEC'
                     + N' WHERE S.' + QUOTENAME(@col_fen) + N' <= @p_fin'
                     + N' AND ISNULL(H.FL_FIN_JOURNEE, 0) <> ISNULL(S.FL_FIN_JOURNEE, 0);';
            EXEC sp_executesql @sql, N'@p_fin datetime2(3), @p_nb bigint OUTPUT',
                 @p_fin = @fin, @p_nb = @nb_non_conformes OUTPUT;

            IF @nb_non_conformes > 0
            BEGIN
                SET @msg = N'Archive non conforme pour ' + @tbl_histo + N' : '
                         + CONVERT(NVARCHAR(20), @nb_non_conformes) + N' trace(s) avec un FL_FIN_JOURNEE différent.';
                THROW 50043, @msg, 1;
            END;
        END;

        /* 5. Rétention : traces plus anciennes que NB_MOIS_RETENTION, à
              condition d'être dans l'archive. */
        SET @sql = N'DELETE S FROM ' + @src + N' AS S'
                 + N' WHERE S.' + QUOTENAME(@col_fen) + N' < @p_limite'
                 + N'   AND EXISTS (SELECT 1 FROM ' + @tgt + N' AS H'
                 + N'   WHERE H.LB_LSN_COMMIT_TEC = S.LB_LSN_COMMIT_TEC AND H.LB_SEQVAL_TEC = S.LB_SEQVAL_TEC);'
                 + N' SELECT @p_nb = @@ROWCOUNT;';
        SET @limite = DATEADD(MONTH, -@retention, @fin);
        EXEC sp_executesql @sql, N'@p_limite datetime2(3), @p_nb bigint OUTPUT',
             @p_limite = @limite, @p_nb = @nb_purgees OUTPUT;

        COMMIT TRANSACTION;

        INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
            (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
        VALUES (@ID_TRT_ALI, @LB_PROJET, N'ARCHIVE OIT [' + CONVERT(NVARCHAR(10), @jour_max, 23) + N']',
                @tbl_ods, @tbl_histo, @nb_a_traiter, N'OK',
                N'Archivées: ' + CONVERT(NVARCHAR(20), @nb_ins_histo)
                + N' (remplacées: ' + CONVERT(NVARCHAR(20), @nb_supp_histo) + N')'
                + N' / purgées du sas: ' + CONVERT(NVARCHAR(20), @nb_purgees)
                + N' / frontière ' + CONVERT(NVARCHAR(23), @fin, 121) + N'.',
                @dt_step, SYSDATETIME());
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @nb_ko = @nb_ko + 1;
        SET @msg = ERROR_MESSAGE()
                 + N' [erreur ' + CONVERT(NVARCHAR(20), ERROR_NUMBER())
                 + N', ligne ' + CONVERT(NVARCHAR(20), ERROR_LINE()) + N']';
        INSERT INTO <?=odiRef.getObjectName("L", "ORT_AUDIT_CHARGEMENT", "MSSQL_DWH", "D") ?>
            (ID_TRT_ALI, LB_PROJET, LB_CHARGEMENT, LB_SOURCE, LB_CIBLE, NB_LIGNE, CD_STATUT, LB_ERREUR, DT_DEBUT, DT_FIN)
        VALUES (@ID_TRT_ALI, @LB_PROJET, N'ARCHIVE OIT [' + CONVERT(NVARCHAR(10), @jour_max, 23) + N']',
                @tbl_ods, @tbl_histo, 0, N'KO', @msg, @dt_step, SYSDATETIME());
    END CATCH;

    FETCH NEXT FROM cur_tables INTO @tbl_ods, @retention;
END;

CLOSE cur_tables;
DEALLOCATE cur_tables;

IF @nb_ko > 0
BEGIN
    SET @msg = N'IWI.009 ARCHIVE OIT : ' + CONVERT(NVARCHAR(10), @nb_ko)
             + N' table(s) non archivée(s), transactions annulées. Les traces restent'
             + N' dans le sas et seront reprises à la prochaine exécution.';
    THROW 50045, @msg, 1;
END;
